#include "actor.h"
#include "../v11/search.h"
int main(int argc,char**argv){try{init();Learner base;base.load("training/v7/base.ntd");v9::Net net;net.load(argv[1]);RNG rng{123};Game g;g.reset(rng);ActorState s{g.b,g.next,opening(g)};auto o=distribution(s,base,net,.1);int chosen=o.greedy;std::array<float,v9::N>grad{};for(int d=0;d<4;d++)if(!o.f[d].empty())net.backward(o.f[d],o.h[d],0,float(-.7*((d==chosen?1:0)-o.p[d])/.1),grad);auto loss=[&](){return -.7*std::log(distribution(s,base,net,.1).p[chosen]);};int checked=0;for(int j=0;j<v9::N&&checked<20;j++)if(std::abs(grad[j])>.001){float old=net.w[j],eps=.0005;net.w[j]=old+eps;double up=loss();net.w[j]=old-eps;double down=loss();net.w[j]=old;double numeric=(up-down)/(2*eps);if(std::abs(numeric-grad[j])>.03*(1+std::abs(numeric)))throw std::runtime_error("policy gradient mismatch");checked++;}if(checked<10)throw std::runtime_error("insufficient gradients");RootPolicySearch original(base,net);for(int k=0;k<80;k++){ActorState current{g.b,g.next,opening(g)};auto direct=distribution(current,base,net,1);original.nodes.clear();original.table.clear();int root=original.node(g.b,g.next,current.c);original.applyPrior(root);int best=-1;double top=-1;for(int d=0;d<4;d++)if(original.nodes[root]->edges[d].move.size&&original.nodes[root]->edges[d].prior>top){top=original.nodes[root]->edges[d].prior;best=d;}if(best!=direct.greedy)throw std::runtime_error("root-prior action mismatch");g.reset(rng);}std::cout<<"80 original-root-prior versus direct-student action parity checks passed; "<<checked<<" policy-gradient finite differences passed; descent sign includes terminal advantage and sampling temperature\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
